const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const ctx={window:{addEventListener(){}},document:{documentElement:{lang:'uk'},addEventListener(){}},profileStorage:{getItem:()=>null}};vm.createContext(ctx);
for(const f of ['assets/vocabulary/recorded-audio.js','assets/adaptive/dialogue-voice.js','assets/adaptive/fox-conversation.js','assets/adaptive/karl-conversation.js','assets/adaptive/benno-audio.js','assets/adaptive/benno-conversation.js','assets/adaptive/gear-dialogue-audio.js','assets/adaptive/gear-conversation.js'])vm.runInContext(fs.readFileSync(f,'utf8'),ctx);
const html=fs.readFileSync('index.html','utf8');vm.runInContext(html.slice(html.indexOf('const AUDIO_MAP='),html.indexOf('let currentAudio='))+html.slice(html.indexOf('function audioKey('),html.indexOf('let speechRun=')),ctx);vm.runInContext(fs.readFileSync('assets/adaptive/three-island-adventure.js','utf8'),ctx);
const a=ctx.window.DEUTSCH_THREE_ISLAND_ADVENTURE,all=a.tasks();assert.equal(all.length,18);assert.equal(new Set(all.map(x=>x.id)).size,18);assert.equal(a.chapters.length,4);for(const q of all){assert(fs.existsSync(q.answerPath),q.answer);if(q.prompt)assert(fs.existsSync(q.prompt.path),q.prompt.text);if(q.reply)assert(fs.existsSync(q.reply.path));assert(q.meaning.every(Boolean));assert.equal(a.match(q,q.answer.toUpperCase()),q.answer);assert.equal(a.match(q,'Unrelated phrase'),null);for(const alt of q.alternatives||[])assert.equal(a.match(q,alt),alt)}
const sequences=new Set();let previous=[];for(let i=0;i<50;i++){const p=a.plan(previous);assert.equal(p.length,18);assert.equal(new Set(p.map(x=>x.id)).size,18);assert.deepEqual(Array.from(p.slice(0,3),x=>x.id),['arrival:hello','arrival:name','arrival:ask']);assert.equal(p[3].id,'profile:hello');assert.equal(p[7].id,'profile:bye');assert.equal(p[8].id,'market:hello');assert.equal(p[12].id,'market:thanks');assert.equal(p[16].id,'gear:thanks');assert.equal(p[17].id,'gear:bye');assert(p.slice(4,7).every(x=>x.chapter===1));assert(p.slice(9,12).every(x=>x.chapter===2));assert(p.slice(13,16).every(x=>x.chapter===3));if(previous.length){for(const [start,end]of [[4,7],[9,12],[13,16]])assert.notEqual(p.slice(start,end).map(x=>x.id).join('|'),previous.slice(start,end).join('|'))}previous=p.map(x=>x.id);sequences.add(previous.join('|'))}assert(sequences.size>1);assert(a.panel((ua,en)=>ua).includes('threeIslandOpen'));console.log('PASS mixed adventure: 18 existing whole actor replies, four coherent scenes, exact alternatives, unique context-safe shuffled plans, no immediately repeated question/item order');
